#!/usr/bin/env python3
"""Emit a kernel-checked convolution certificate for the target-sum code."""
from pathlib import Path

RADIX, CHAINS, TARGET = 16, 32, 150
DESTINATION = Path(__file__).resolve().parents[1] / 'XmssSecurity/Proof/TargetSum/EncodingCardinalityCertificate.lean'


def generate():
    lines = [
        'import XmssSecurity.Proof.TargetSum.EncodingCardinality',
        'import XmssSecurity.Proof.TargetSum.Code', '',
        '/-! Generated by scripts/generate_encoding_count.py.',
        'Each row equation is checked by the kernel, without native_decide. -/', '',
        'set_option maxRecDepth 2000', 'set_option maxHeartbeats 2000000', '',
        'namespace XmssSecurity.TargetSum.TargetSum', '',
    ]
    row = [1] + [0] * TARGET
    for length in range(CHAINS + 1):
        if length:
            row = [sum(row[total - digit] for digit in range(RADIX) if digit <= total)
                   for total in range(TARGET + 1)]
        last = min((RADIX - 1) * length, TARGET)
        lines += [f'private def row{length} : List ℕ := [']
        values = row[:last + 1]
        for start in range(0, len(values), 8):
            lines.append('  ' + ', '.join(map(str, values[start:start + 8])) +
                         (',' if start + 8 < len(values) else ']' +
                          (f' ++ List.replicate {TARGET - last} 0' if last < TARGET else '')))
        lines += ['', f'private theorem row{length}_eq : countRow {RADIX} {TARGET} {length} = row{length} := by']
        if length:
            lines.append(f'  rw [countRow, row{length - 1}_eq]')
        lines += ['  decide +kernel', '']
    lines += [
        '/-- The exact number of 32-digit radix-sixteen words with sum 330. -/',
        'theorem wordCount_sixteen_thirtyTwo_330 :',
        f'    wordCount {RADIX} {CHAINS} 330 = {row[TARGET]} := by',
        '  rw [wordCount_complement_330]',
        f'  rw [← countRow_getD_eq_wordCount {RADIX} {TARGET} {CHAINS} {TARGET} le_rfl, row{CHAINS}_eq]',
        '  decide +kernel', '', 'end XmssSecurity.TargetSum.TargetSum', '',
    ]
    return '\n'.join(lines)


if __name__ == '__main__':
    DESTINATION.write_text(generate())
